 "content": "def transform(grid):
    """Project each colored cross into four straight rays.

    A cross is a nonzero, non-3 center with four adjacent 3 arms. Rays begin
    immediately beyond each arm, continue until the next 3 marker or edge,
    and color only zero cells (preserving any existing colored centers).
    """
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    centers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] not in (0, 3)
               and 0 < r < h - 1 and 0 < c < w - 1
               and grid[r-1][c] == 3 and grid[r+1][c] == 3
               and grid[r][c-1] == 3 and grid[r][c+1] == 3]

    # Horizontal rays first; then vertical rays. Existing nonzero cells are
    # retained, while rays pass through them unless a 3 marker blocks them.
    for r, c, color in centers:
        for dc in (-1, 1):
            j = c + 2 * dc
            while 0 <= j < w and grid[r][j] != 3:
                if out[r][j] == 0:
                    out[r][j] = color
                j += dc
    for r, c, color in centers:
        for dr in (-1, 1):
            i = r + 2 * dr
            while 0 <= i < h and grid[i][c] != 3:
                if out[i][c] == 0:
                    out[i][c] = color
                i += dr
    return out
