 "content": "def transform(grid):
    """Extend each four-arm colored cross outward in four straight rays.

    Rays start beyond the cross's 3 arms and stop at the next 3 marker or
    grid edge. If beams intersect, vertical beams take precedence over
    horizontal ones, while original nonzero cells are preserved.
    """
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    centers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] not in (0, 3)
               and 0 < r < h - 1 and 0 < c < w - 1
               and grid[r-1][c] == 3 and grid[r+1][c] == 3
               and grid[r][c-1] == 3 and grid[r][c+1] == 3]

    def paint(r, c, color):
        # Preserve all cells that were nonzero in the original input.
        if grid[r][c] == 0:
            out[r][c] = color

    for r, c, color in centers:
        for dc in (-1, 1):
            j = c + 2 * dc
            while 0 <= j < w and grid[r][j] != 3:
                paint(r, j, color)
                j += dc
    for r, c, color in centers:
        for dr in (-1, 1):
            i = r + 2 * dr
            while 0 <= i < h and grid[i][c] != 3:
                paint(i, c, color)
                i += dr
    return out
