{
 "content": "def transform(grid):
    """Extend colored cross motifs into straight rays, respecting blank lanes.

    A colored source is a nonzero/non-3 center with four adjacent 3 arms.
    Rays continue beyond each arm until a later 3 marker or the grid edge.
    Empty 3-armed crosses mark a protected vertical lane; colored rays do not
    paint that lane. Original nonzero cells are preserved, and vertical rays
    take precedence at intersections.
    """
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    sources = []
    blank_columns = set()
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            cross = (grid[r-1][c] == 3 and grid[r+1][c] == 3
                     and grid[r][c-1] == 3 and grid[r][c+1] == 3)
            if not cross:
                continue
            if grid[r][c] == 0:
                blank_columns.add(c)
            elif grid[r][c] != 3:
                sources.append((r, c, grid[r][c]))

    # Paint horizontal beams first. A 3 marker blocks a beam but is preserved.
    for r, c, color in sources:
        for dc in (-1, 1):
            j = c + 2 * dc
            while 0 <= j < w and grid[r][j] != 3:
                if grid[r][j] == 0 and j not in blank_columns:
                    out[r][j] = color
                j += dc

    # Vertical beams override horizontal colors at intersections.
    for r, c, color in sources:
        for dr in (-1, 1):
            i = r + 2 * dr
            while 0 <= i < h and grid[i][c] != 3:
                if grid[i][c] == 0 and c not in blank_columns:
                    out[i][c] = color
                i += dr
    return out
