 "content": "def transform(grid):
    """Extend colored 3-armed crosses as axis-aligned rays.

    Each nonzero/non-3 center with 3 markers in all four adjacent cells emits
    rays along its row and column, starting just beyond its four arms. Rays
    stop at a subsequent 3 marker or the grid edge, and color only zero cells.
    A separate zero-centered 3-cross reserves its column as a blank lane.
    Horizontal rays are drawn first, then vertical rays.
    """
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    sources = []
    blank_cols = set()
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if (grid[r-1][c] == grid[r+1][c] == 3 and
                grid[r][c-1] == grid[r][c+1] == 3):
                if grid[r][c] == 0:
                    blank_cols.add(c)
                elif grid[r][c] != 3:
                    sources.append((r, c, grid[r][c]))

    for r, c, color in sources:
        for dc in (-1, 1):
            j = c + 2 * dc
            while 0 <= j < w and grid[r][j] != 3:
                if grid[r][j] == 0 and j not in blank_cols:
                    out[r][j] = color
                j += dc

    for r, c, color in sources:
        for dr in (-1, 1):
            i = r + 2 * dr
            while 0 <= i < h and grid[i][c] != 3:
                if grid[i][c] == 0 and c not in blank_cols:
                    out[i][c] = color
                i += dr
    return out
