{
 "content": "def transform(grid):
    """Extend colored four-arm crosses along their rows and columns.

    Each nonzero/non-3 center surrounded by 3 markers emits rays from just
    beyond its arms, stopping at the next 3 marker or grid edge. Paint only
    zero cells. A complete 3-cross with an empty center reserves its column
    from horizontal rays. Horizontal rays are painted first and vertical rays
    take precedence where rays intersect.
    """
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    centers = [
        (r, c, grid[r][c])
        for r in range(1, h - 1)
        for c in range(1, w - 1)
        if grid[r][c] not in (0, 3)
        and grid[r - 1][c] == grid[r + 1][c] == 3
        and grid[r][c - 1] == grid[r][c + 1] == 3
    ]

    blank_columns = {
        c
        for r in range(1, h - 1)
        for c in range(1, w - 1)
        if grid[r][c] == 0
        and grid[r - 1][c] == grid[r + 1][c] == 3
        and grid[r][c - 1] == grid[r][c + 1] == 3
    }

    # Horizontal rays do not fill columns occupied by empty-center crosses.
    for r, c, color in centers:
        for dc in (-1, 1):
            j = c + 2 * dc
            while 0 <= j < w and grid[r][j] != 3:
                if grid[r][j] == 0 and j not in blank_columns:
                    out[r][j] = color
                j += dc

    # Vertical rays are applied second, so they win at crossings.
    for r, c, color in centers:
        for dr in (-1, 1):
            i = r + 2 * dr
            while 0 <= i < h and grid[i][c] != 3:
                if grid[i][c] == 0:
                    out[i][c] = color
                i += dr
    return out
